def read(f):return json.loads(Path(f).read_text())
def put(f,x):Path(f).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
d=read('source-'+b+'-modern-da.json'); en=read('source-'+b+'-modern-en.json')
